mapper.select:
select id, game_name, game_year, game_type, game_size, game_price, game_description, game_cover, game_download_link, game_extract_code from game


        game_name like concat('%', #{gameName}, '%')


        and game_year >= #{beginYear}


        and game_year <= #{endYear}


        and game_type = #{gameType}



            and game_size < 5


            and game_size >= 5 and game_size < 10


            and game_size >= 10 and game_size <= 20


            and game_size >= 20 and game_size < 50


            and game_size >= 50
